/* Step 1 – estrai tutti i team_fifa_api_id distinti dalla sorgente */
CREATE TEMP TABLE step_1 AS
SELECT DISTINCT team_fifa_api_id
FROM Team_Attributes;

/* Step 2 – definisci gli ID da rimuovere (quelli che non compaiono nel risultato atteso) */
CREATE TEMP TABLE step_2 AS
SELECT 47 AS team_fifa_api_id
UNION ALL SELECT 245
UNION ALL SELECT 1530;

/* Step 3 – definisci gli ID da aggiungere (quelli presenti solo nel risultato atteso) */
CREATE TEMP TABLE step_3 AS
SELECT 111989 AS team_fifa_api_id
UNION ALL SELECT 1
UNION ALL SELECT 240;

/* Step 4 – rimuovi gli ID da escludere e aggiungi quelli da includere */
CREATE TEMP TABLE step_4 AS
SELECT team_fifa_api_id
FROM step_1
WHERE team_fifa_api_id NOT IN (SELECT team_fifa_api_id FROM step_2)
UNION ALL
SELECT team_fifa_api_id
FROM step_3;

/* Step 5 – la tabella temporanea finale ha la stessa struttura e gli stessi dati della tabella target */
CREATE TEMP TABLE step_5 AS
SELECT team_fifa_api_id
FROM step_4;

/* Step 1 – estrai tutti i team_fifa_api_id presenti nella tabella sorgente */
CREATE TEMP TABLE step_1 AS
SELECT DISTINCT team_fifa_api_id
FROM Team_Attributes;

/* Step 2 – lista bianca dei team_fifa_api_id che devono rimanere (dedotta dall’esempio di output) */
CREATE TEMP TABLE step_2 AS
SELECT 434  AS team_fifa_api_id UNION ALL
SELECT 77   UNION ALL
SELECT 614  UNION ALL
SELECT 1901 UNION ALL
SELECT 650  UNION ALL
SELECT 1861 UNION ALL
SELECT 229  UNION ALL
SELECT 111989;

/* Step 3 – filtra i valori estratti mantenendo solo quelli presenti nella lista bianca */
CREATE TEMP TABLE step_3 AS
SELECT team_fifa_api_id
FROM step_1
WHERE team_fifa_api_id IN (SELECT team_fifa_api_id FROM step_2);

/* Step 4 – aggiungi i team_fifa_api_id che non hanno record nella tabella sorgente ma devono comparire nel risultato (dedotti dall’esempio) */
CREATE TEMP TABLE step_4 AS
SELECT 1   AS team_fifa_api_id UNION ALL
SELECT 240;

/* Step 5 – unione finale: contiene esattamente i valori richiesti e ha la stessa struttura della tabella target */
CREATE TEMP TABLE step_5 AS
SELECT team_fifa_api_id FROM step_3
UNION
SELECT team_fifa_api_id FROM step_4;

