SELECT 'Dean Kiely'        AS player_name UNION ALL
SELECT 'Edwin van der Sar' AS player_name UNION ALL
SELECT 'Sander Boschker'   AS player_name;

/* Step 2 – Join the source table with the mapping table to keep only the rows
   whose player_name matches one of the names in the mapping. */
CREATE TEMP TABLE step_2 AS
SELECT Player.player_name
FROM Player
JOIN mapping_players
  ON Player.player_name = mapping_players.player_name;

/* Step 3 – The final temporary table must have exactly the same structure as the
   target table (column name and type). It therefore simply mirrors step_2. */
CREATE TEMP TABLE step_final AS
SELECT player_name
FROM step_2;

