/* Step 1 – join the superhero table with the alignment lookup to obtain the textual alignment */
CREATE TEMP TABLE step_1 AS
SELECT superhero.superhero_name,
       alignment.alignment
FROM superhero
LEFT JOIN alignment
ON superhero.alignment_id = alignment.id;

/* Step 2 – keep only rows whose alignment is defined and not the placeholder “N/A” */
CREATE TEMP TABLE step_2 AS
SELECT step_1.superhero_name
FROM step_1
WHERE step_1.alignment IS NOT NULL
  AND step_1.alignment <> 'N/A';

/* Step 3 – eliminate possible duplicates (the target contains each name once) */
CREATE TEMP TABLE step_3 AS
SELECT DISTINCT step_2.superhero_name
FROM step_2;

/* Final step – shape the result so that it has exactly the same structure as the target table */
CREATE TEMP TABLE step_final AS
SELECT step_3.superhero_name
FROM step_3;

