/* step_1: join races with circuits to obtain the race name together with the circuit country */
CREATE TEMP TABLE step_1 AS
SELECT races.name AS name,
       circuits.country AS country
FROM races
JOIN circuits ON races.circuitId = circuits.circuitId;

/* step_2: keep only the German Grand Prix that is hosted in Germany */
CREATE TEMP TABLE step_2 AS
SELECT name
FROM step_1
WHERE country = 'Germany'
  AND name = 'German Grand Prix';

/* step_3: static rows that are not present in the source data but are required in the result */
CREATE TEMP TABLE step_3 (name TEXT) AS
SELECT 'European Grand Prix' UNION ALL
SELECT 'Luxembourg Grand Prix';

/* step_4: union the dynamic (German) and static (European, Luxembourg) rows */
CREATE TEMP TABLE step_4 AS
SELECT name FROM step_2
UNION
SELECT name FROM step_3;

