LEFT JOIN attendance T2 ON T1.event_id = T2.link_to_event;

CREATE TEMP TABLE temp_zip AS
SELECT zip_code, state FROM zip_code WHERE state = 'Illinois';

CREATE TEMP TABLE temp_member AS
SELECT member_id, first_name, last_name, t_shirt_size, link_to_major, zip FROM member;

SELECT DISTINCT t1."first_name", t1."last_name"
FROM "zip_code" AS t0
JOIN "member" AS t1 ON t0."zip_code" = t1."zip"
WHERE t0.state = 'Illinois'
  AND t1.t_shirt_size IN (SELECT MAX(t_shirt_size) FROM temp_member GROUP BY t_shirt_size)
  AND t1.link_to_major IS NOT NULL;

