CREATE TEMP TABLE temp_member AS
SELECT "first_name", "last_name" FROM "member" WHERE "position" = 'President';

CREATE TEMP TABLE temp_expense AS
SELECT T1."expense_id", T1."cost", T2."link_to_major"
FROM "expense" AS T1
JOIN "member" AS T2 ON T1."link_to_member" = T2."member_id"
WHERE T2."position" = 'President';

CREATE TEMP TABLE temp_join AS
SELECT T3."first_name", T3."last_name", SUM(T4."cost") AS total_cost
FROM temp_member AS T3
JOIN temp_expense AS T4 ON T3."first_name" = T4."first_name"
GROUP BY T3."first_name", T3."last_name";

SELECT "first_name", "last_name", "SUM(total_cost)" FROM temp_join;

